CREATE TABLE IF NOT EXISTS generator_analysis ( id int(11) NOT NULL AUTO_INCREMENT, generator_id int(11) NOT NULL, reading_date date NOT NULL, expected_fuel decimal(10,2) DEFAULT NULL, actual_fuel decimal(10,2) DEFAULT NULL, fuel_difference decimal(10,2) DEFAULT NULL, efficiency decimal(10,2) DEFAULT NULL, health_score int(11) DEFAULT NULL, status varchar(50) DEFAULT NULL, created_at timestamp NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (id), FOREIGN KEY (generator_id) REFERENCES generators (id) ON DELETE CASCADE, UNIQUE KEY unique_gen_date (generator_id, reading_date) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS generator_predictions ( id int(11) NOT NULL AUTO_INCREMENT, generator_id int(11) NOT NULL, prediction_date date NOT NULL, predicted_fuel decimal(10,2) DEFAULT NULL, predicted_cost decimal(10,2) DEFAULT NULL, predicted_remaining_days decimal(10,2) DEFAULT NULL, predicted_efficiency decimal(10,2) DEFAULT NULL, created_at timestamp NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (id), FOREIGN KEY (generator_id) REFERENCES generators (id) ON DELETE CASCADE, UNIQUE KEY unique_gen_pred_date (generator_id, prediction_date) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS generator_alerts ( id int(11) NOT NULL AUTO_INCREMENT, generator_id int(11) NOT NULL, alert_type varchar(50) NOT NULL, severity enum('Low','Medium','High','Critical') DEFAULT 'Low', message text NOT NULL, created_at timestamp NOT NULL DEFAULT current_timestamp(), resolved_at datetime DEFAULT NULL, PRIMARY KEY (id), FOREIGN KEY (generator_id) REFERENCES generators (id) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
